const STORE='svoy-golos-v1';
let state={completed:{},mastered:{},sessions:[],last:null,pattern:null,focus:'speech'};
try{const saved=JSON.parse(localStorage.getItem(STORE)||'null');if(saved&&typeof saved==='object')state={...state,...saved};}catch{}
if(!state.completed||Array.isArray(state.completed)||typeof state.completed!=='object')state.completed={};
