const formatTime=n=>`${Math.floor(Math.max(0,n)/60)}:${String(Math.max(0,n)%60).padStart(2,'0')}`;
const toast=text=>{const el=$('#toast');el.textContent=text;el.style.display='block';clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>el.style.display='none',4500);};
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch{toast('Не удалось сохранить. Скачай резервную копию в «Прогрессе».');}}
function courseLessons(id){return LESSONS.filter(l=>l.course===id);}
function nextLesson(id){return TrainingPlan.recommend(id,LESSONS,state.mastered)||courseLessons(id).at(-1);}
function courseProgress(id){const ls=courseLessons(id);return [ls.filter(l=>state.mastered[l.id]).length,ls.length];}
function courseCard(c){const [done,total]=courseProgress(c.id);return `<a class="card course-card" href="#course/${c.id}"><div class="row between"><span class="num">${c.number}</span><span aria-hidden="true">→</span></div><h3>${c.name}</h3><p>${c.description}</p><footer><span>${total} занятий · ${c.duration}</span><span>${done}/${total}</span></footer><div class="bar" aria-label="Освоено ${done} из ${total}"><b style="width:${done/total*100}%"></b></div></a>`;}
function prettyDate(value){return new Date(value+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long'});}
function renderBlocks(){const current=TrainingPlan.block(LESSONS,state.mastered);return `<section class="section"><div class="block-grid">${TrainingPlan.BLOCKS.map((b,i)=>{const ls=LESSONS.filter(l=>l.block===i),done=ls.filter(l=>state.mastered[l.id]).length;return `<article class="card block-card ${i===current?'current':''}"><div class="eyebrow">Блок ${i+1} · ${done===ls.length?'Освоен':i===current?'Сейчас':'Впереди'}</div><h3>${b.name}</h3><small>${done} из ${ls.length} навыков</small><div class="bar"><b style="width:${done/ls.length*100}%"></b></div></article>`;}).join('')}</div></section>`;}
function renderWeek(today,plan){const start=TrainingPlan.monday(today);return `<section class="section"><ol class="week-plan">${Array.from({length:7},(_,i)=>{const day=TrainingPlan.add(start,i),cs=TrainingPlan.schedule(day,plan.startedOn);return `<li class="${day===today?'current':''}" ${day===today?'aria-current="date"':''}><div><strong>${TrainingPlan.DAYS[TrainingPlan.weekday(day)]}</strong><small>${prettyDate(day)}${day===today?' · сегодня':''}</small></div><span>${cs.length?cs.map(id=>COURSES.find(c=>c.id===id).name).join(' + '):'Отдых'}</span></li>`;}).join('')}</ol></section>`;}
function renderToday(){const today=TrainingPlan.date(),plan=TrainingPlan.ensure(state,LESSONS,today),lesson=TrainingPlan.task(state,LESSONS,today),block=TrainingPlan.block(LESSONS,state.mastered);save();const deferred=plan.pending&&plan.pending.availableOn>today;let hero;
if(lesson){const c=COURSES.find(c=>c.id===lesson.course),last=state.sessions.slice().reverse().find(s=>s.id===lesson.id&&s.practiced),resume=state.last?.id===lesson.id;hero=`<section class="hero"><div class="eyebrow">${TrainingPlan.weekday(today)===0?'Добровольный повтор':plan.pending.date<today?'Перенесённое занятие':'Сегодня'} · ${c.name}</div><h2>${lesson.title}</h2><p>Блок ${lesson.block+1} «${TrainingPlan.BLOCKS[lesson.block].name}» · около ${Math.ceil(lesson.steps.reduce((n,s)=>n+s.seconds,0)/60)} мин</p><p class="desc">${esc(lesson.goal)}</p>${last?`<p class="plan-feedback">${state.mastered[lesson.id]?'Повтор':'Закрепление'}${last.note?`<br>Твоя заметка: ${esc(last.note)}`:''}</p>`:''}<div class="tools-row"><a class="btn light" href="#lesson/${lesson.id}">${resume?'Продолжить':'Начать занятие'} →</a><button class="btn secondary" id="defer-day">Перенести на завтра</button></div></section>`;}
else{hero=`<section class="hero"><div class="eyebrow">${prettyDate(today)}</div><h2>${block===4?'Четыре блока пройдены':deferred?'Занятие перенесено':plan.closedOn===today?'На сегодня достаточно':'День отдыха'}</h2><p class="desc">${block===4?'Можно возвращаться к контрольным заданиям и своим проектам.':deferred?`Продолжим ${prettyDate(plan.pending.availableOn)}.`:plan.closedOn===today?'Занятие сохранено.':'Можно отдохнуть или выбрать повтор.'}</p>${deferred?'<button class="btn light" id="resume-day">Вернуть на сегодня</button>':'<a class="btn light" href="#courses">Выбрать добровольный повтор →</a>'}</section>`;}
return `<h1>Сегодня</h1><p class="intro">${prettyDate(today)} · ${block<4?TrainingPlan.BLOCKS[block].name:'Свободная практика'}</p>${hero}<div class="tools-row"><a class="icon-btn" href="#courses">Все занятия</a><a class="icon-btn" href="#progress">Прогресс</a></div><details><summary>Неделя</summary>${renderWeek(today,plan)}</details><details><summary>Учебные блоки</summary>${renderBlocks()}</details><div class="tools-row"><a class="icon-btn" href="#install">Установить</a><a class="icon-btn" href="#method">Справка</a></div>`;}

function bindToday(){const b=$('#defer-day');if(b)b.onclick=()=>{TrainingPlan.defer(state,LESSONS);save();route();toast('Перенесено на завтра. Задание сохранено.');};const r=$('#resume-day');if(r)r.onclick=()=>{if(state.plan?.pending)state.plan.pending.availableOn=TrainingPlan.date();save();route();};}
function renderCourse(id){const c=COURSES.find(x=>x.id===id);if(!c)return notFound();return `<a href="#courses" class="back">← Все направления</a><div class="eyebrow">Свободный выбор · направление ${c.number}</div><h1>${c.name}</h1>${TrainingPlan.BLOCKS.map((b,k)=>`<section class="section"><h2>Блок ${k+1}. ${b.name}</h2><ol class="lesson-list">${courseLessons(id).filter(l=>l.block===k).map(l=>`<li><a href="#lesson/${l.id}"><span class="badge">${state.mastered[l.id]?'✓':String(l.position).padStart(2,'0')}</span><div><strong>${l.title}</strong><small>${l.focus}${state.completed[l.id]&&!state.mastered[l.id]?' · повтор':''} · ${l.steps.reduce((s,x)=>s+x.seconds,0)/60} мин${l.home?' · на месте':''}</small></div><span class="arrow">→</span></a></li>`).join('')}</ol></section>`).join('')}`;}
function notFound(){return '<h1>Такого занятия нет</h1><a class="btn" href="#courses">Открыть курсы</a>';}
function hasNarration(lesson){const clips=window.VOICE_CLIPS?.[lesson.id];return Array.isArray(clips)&&clips.length===lesson.steps.length&&clips.every(Boolean);}
function renderSession(id){const lesson=LESSONS.find(l=>l.id===id);if(!lesson)return notFound();session=lesson;state.focus=lesson.course;stepIndex=state.last?.id===id?Math.min(Math.max(Number(state.last.step)||0,0),lesson.steps.length-1):0;remaining=lesson.steps[stepIndex].seconds;state.last={id,step:stepIndex};save();return `<div class="reader"><a href="#course/${lesson.course}" class="back">← ${COURSES.find(c=>c.id===lesson.course).name}</a><h1>${lesson.title}</h1><p class="tiny muted">${TrainingPlan.BLOCKS[lesson.block].name} · занятие ${lesson.position}</p><details><summary>Цель и проверка</summary><p>${esc(lesson.goal)}</p><ul>${lesson.criteria.map(c=>`<li>${esc(c)}</li>`).join('')}</ul>${lesson.previous?`<a class="icon-btn" href="#lesson/${lesson.previous}">Предыдущее занятие</a>`:''}</details>${!lesson.home&&hasNarration(lesson)?`<label class="row"><input id="listen-mode" type="checkbox"> Автопереход с озвучкой</label>`:''}${hasNarration(lesson)?'<div class="tools-row"><button class="icon-btn" id="save-lesson-audio">Голос офлайн</button><span class="tiny muted" id="voice-download-status" role="status"></span></div>':''}<div id="step"></div><details><summary>Записать дубль</summary>${recordControls()}<div id="record-list"></div></details></div>`;}
function renderStep(){if(!session)return;const s=session.steps[stepIndex];const wrap=$('#step');if(!wrap)return;wrap.innerHTML=`<div class="row between stephead"><span class="eyebrow">Шаг ${stepIndex+1} из ${session.steps.length}</span><span class="tiny muted">${formatTime(s.seconds)}</span></div><div class="bar"><b style="width:${(stepIndex+1)/session.steps.length*100}%"></b></div><article class="card task-card section"><h2>${s.title}</h2><p class="task-text">${esc(s.instruction)}</p>${session.version===2&&stepIndex>=2?`<details ${stepIndex===2?'open':''}><summary>Напомнить основную задачу</summary><p>${esc(session.steps[1].instruction)}</p><div class="sample">${esc(session.steps[1].text)}</div></details>`:''}${s.text?`<div class="sample">${esc(s.text)}</div>`:''}<details><summary>На что обратить внимание</summary><p>${esc(s.check)}</p></details>${s.notes?`<div class="tools-row"><button class="btn secondary small" id="example">${s.recall?'♪ Проверить пример':'♪ Послушать пример'}</button><button class="btn secondary small" id="lower" aria-label="Опустить пример на полутон">− Ниже</button><button class="btn secondary small" id="higher" aria-label="Поднять пример на полутон">+ Выше</button></div><p class="tiny muted" id="shift-label">${shift>0?'+':''}${shift} полутонов</p>`:''}<div class="row between timerbar"><span class="timer" id="clock" role="timer">${formatTime(remaining)}</span><button id="timer-toggle" class="btn">${auto?'Слушать и начать':'Начать упражнение'}</button></div><div id="session-status" class="session-status" aria-live="polite"></div></article><div class="task-actions"><button class="btn secondary" id="prev-step" ${stepIndex===0?'disabled':''}>Назад</button><button class="btn" id="next-step">${stepIndex===session.steps.length-1?'Завершить занятие':'Сделал, дальше'} →</button></div>${hasNarration(session)?'<button class="icon-btn" id="speak-step">Озвучить задание</button>':''}`;
if($('#save-lesson-audio'))$('#save-lesson-audio').onclick=saveLessonAudio;
$('#timer-toggle').onclick=toggleTimer;$('#prev-step').onclick=()=>changeStep(-1);$('#next-step').onclick=()=>changeStep(1);if($('#speak-step'))$('#speak-step').onclick=()=>speakStep(false);
if(s.notes){$('#example').onclick=()=>playExample(s.notes,session.course).catch(()=>{});$('#lower').onclick=()=>transpose(-1);$('#higher').onclick=()=>transpose(1);}
const mode=$('#listen-mode');if(mode){mode.checked=auto;mode.onchange=()=>{pauseSession();auto=mode.checked;renderStep();};}
}
function transpose(delta){shift=Math.max(-12,Math.min(12,shift+delta));$('#shift-label').textContent=`${shift>0?'+':''}${shift} полутонов`;}
function status(text){if($('#session-status'))$('#session-status').textContent=text;}
function updateClock(){if($('#clock'))$('#clock').textContent=formatTime(remaining);}
function stopSpeech(){speechVersion++;clearTimeout(narrationTimeout);if(narrationAudio){narrationAudio.onended=null;narrationAudio.onerror=null;narrationAudio.onplaying=null;narrationAudio.onwaiting=null;narrationAudio.pause();narrationAudio.removeAttribute('src');narrationAudio.load();narrationAudio=null;}if('speechSynthesis'in window)speechSynthesis.cancel();narrating=false;utterance=null;}
let wakeLock=null;
async function keepAwake(){try{if(auto&&navigator.wakeLock&&!wakeLock)wakeLock=await navigator.wakeLock.request('screen');}catch{}}
function releaseAwake(){if(wakeLock){wakeLock.release().catch(()=>{});wakeLock=null;}}
function pauseSession(){releaseAwake();clearInterval(timer);timer=null;stopSpeech();stopAudio(false);if($('#timer-toggle'))$('#timer-toggle').textContent=auto?'Продолжить слушать':'Продолжить';status('Пауза. Продолжи, когда будет удобно.');}
function beginCountdown(){if(!session)return;if(remaining<=0)remaining=session.steps[stepIndex].seconds;deadline=Date.now()+remaining*1000;$('#timer-toggle').textContent='Пауза';status('Выполняй упражнение. Между повторами отдыхай.');timer=setInterval(()=>{remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));updateClock();if(remaining===0){clearInterval(timer);timer=null;if(auto)changeStep(1,true);else{$('#timer-toggle').textContent='Повторить таймер';status('Время шага закончилось. Нажми «Сделал, дальше», когда будешь готов.');}}},250);}
function toggleTimer(){if(timer||narrating){pauseSession();return;}if(auto)speakStep(true);else beginCountdown();}
function speakStep(countAfter){
 if(!session)return;
 pauseSession();
 const s=session.steps[stepIndex],token=++speechVersion;
 const src=window.VOICE_CLIPS?.[session.id]?.[stepIndex];
 if(!src){status('Запись задания недоступна. Можно прочитать текст и запустить таймер.');return;}
 const audio=new Audio(src);narrationAudio=audio;narrating=true;keepAwake();
 $('#timer-toggle').textContent='Пауза';status('Загружается голос…');
 const failed=()=>{if(token!==speechVersion)return;pauseSession();status('Не удалось загрузить голос. Проверь сеть или сохрани озвучку занятия заранее. Нажми «Озвучить задание», чтобы повторить.');};
 narrationTimeout=setTimeout(failed,20000);
 audio.onplaying=()=>{if(token!==speechVersion)return;clearTimeout(narrationTimeout);status('Слушай задание. После него будет время для повтора.');};
 audio.onwaiting=()=>{if(token===speechVersion){clearTimeout(narrationTimeout);narrationTimeout=setTimeout(failed,20000);}};
 audio.onerror=failed;
 audio.onended=async()=>{
  if(token!==speechVersion)return;
  clearTimeout(narrationTimeout);narrating=false;narrationAudio=null;
  if(countAfter){
   if(s.notes&&!s.recall){try{await playExample(s.notes,session.course);}catch{pauseSession();status('Пример недоступен. Повтори загрузку.');return;}}
   if(token===speechVersion&&session)beginCountdown();
  }else{releaseAwake();if($('#timer-toggle'))$('#timer-toggle').textContent='Начать упражнение';status('Задание озвучено. Можно начать упражнение.');}
 };
 audio.play().catch(failed);
}
async function saveLessonAudio(){
 const button=$('#save-lesson-audio'),label=$('#voice-download-status');if(!session||!button)return;
 const files=[...new Set(window.VOICE_CLIPS?.[session.id]||[])];
 if(!files.length){label.textContent='Записи ещё не доступны.';return;}
 button.disabled=true;
 try{
  const cache=await caches.open('svoy-golos-voice-v1');let count=0;
  for(const file of files){
   const url=new URL(file,location.href).href;
   if(!await cache.match(url)){const r=await fetch(url,{cache:'no-cache'});if(!r.ok||!r.headers.get('content-type')?.includes('audio'))throw Error();await cache.put(url,r);}
   count++;label.textContent=`Сохранено ${count} из ${files.length}`;
  }
  label.textContent='Озвучка этого занятия сохранена. Можно слушать без сети.';
 }catch{label.textContent='Не удалось сохранить всё. Проверь сеть и нажми ещё раз.';}
 finally{button.disabled=false;}
}
function changeStep(delta,fromAuto=false){pauseSession();const next=stepIndex+delta;if(next>=session.steps.length){finishSession(fromAuto);return;}stepIndex=Math.max(0,next);remaining=session.steps[stepIndex].seconds;state.last={id:session.id,step:stepIndex};save();renderStep();window.scrollTo({top:0,behavior:'instant'});if(fromAuto&&auto)speakStep(true);}
function finishSession(fromAuto){pendingFinish=session;state.last=null;save();if(fromAuto)status('Занятие закончено. Оценить результат можно после остановки.');$('#step').innerHTML=`<article class="card task-card section"><div class="eyebrow">Практика завершена</div><h2 style="margin-top:15px">Что получилось сегодня?</h2><label>Лёгкость · 1–5</label><div class="rating">${[1,2,3,4,5].map(n=>`<button type="button" data-rating="${n}" aria-pressed="false">${n}</button>`).join('')}</div><fieldset class="mastery"><legend>Проверка навыка</legend>${session.criteria.map((c,i)=>`<label class="row"><input type="checkbox" class="criterion" data-criterion="${i}"> ${esc(c)}</label>`).join('')}</fieldset><label for="finish-note">Одна мысль о занятии</label><textarea id="finish-note" maxlength="1000" placeholder="Например: стал меньше спешить на концах фраз"></textarea>${session.home?'<label class="row"><input type="checkbox" id="hands-done"> Я выполнил практическое задание руками</label>':''}<button class="btn wide" id="save-finish">Сохранить занятие</button></article>`;
let rating=null;document.querySelectorAll('[data-rating]').forEach(b=>b.onclick=()=>{rating=Number(b.dataset.rating);document.querySelectorAll('[data-rating]').forEach(x=>{x.classList.toggle('chosen',x===b);x.setAttribute('aria-pressed',x===b?'true':'false');});});$('#save-finish').onclick=()=>{const l=pendingFinish;if(!l)return;const practiced=!l.home||$('#hands-done').checked;const checks=[...document.querySelectorAll('.criterion')].map(el=>el.checked);const mastered=practiced&&checks.length===l.criteria.length&&checks.every(Boolean);const entry={mastered,checks,id:l.id,at:new Date().toISOString(),rating,note:$('#finish-note').value.trim(),practiced};state.sessions.push(entry);if(practiced)state.completed[l.id]=entry.at;if(mastered)state.mastered[l.id]=entry.at;TrainingPlan.finish(state,LESSONS,l.id,practiced);save();pendingFinish=null;session=null;location.hash='today';toast(mastered?'Навык отмечен освоенным':practiced?'Практика сохранена. Повтори до выполнения критериев.':'Чтение сохранено. Практику можно выполнить позже.');};}
function recordControls(){return '<div class="tools-row"><button class="btn small" id="record-start">● Записать</button><button class="btn secondary small" id="record-stop" disabled>Остановить</button><span id="record-status" class="tiny muted" aria-live="polite"></span></div>';}
function openDB(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(new Error('Хранилище записей недоступно'));const req=indexedDB.open('svoy-golos-recordings',1);req.onupgradeneeded=()=>req.result.createObjectStore('records',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});return dbPromise;}
async function dbTask(mode,op){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction('records',mode);const req=op(tx.objectStore('records'));let result;req.onsuccess=()=>result=req.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Ошибка сохранения'));});}
function bindRecorder(){if(!$('#record-start'))return;$('#record-start').onclick=startRecording;$('#record-stop').onclick=stopRecording;listRecordings();}
async function startRecording(){if(recorderBusy){toast('Дождись сохранения текущего дубля.');return;}recorderBusy=true;try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw new Error('Запись недоступна. Используй Chrome и защищённое соединение.');await openDB();const lessonId=session?.id||'free';const title=session?.title||'Свободная запись';const startBtn=$('#record-start');startBtn.disabled=true;recordStream=await navigator.mediaDevices.getUserMedia({audio:true});if(!document.contains(startBtn)){recordStream.getTracks().forEach(t=>t.stop());recordStream=null;recorderBusy=false;return;}const type=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t));recorder=type?new MediaRecorder(recordStream,{mimeType:type}):new MediaRecorder(recordStream);recChunks=[];recordStart=Date.now();recorder.ondataavailable=e=>{if(e.data.size)recChunks.push(e.data);};recorder.onstop=async()=>{clearInterval(recordTicker);recordStream?.getTracks().forEach(t=>t.stop());recordStream=null;const blob=new Blob(recChunks,{type:recorder.mimeType});const entry={id:Date.now()+'-'+Math.random().toString(36).slice(2,8),lessonId,title,at:new Date(recordStart).toISOString(),seconds:Math.round((Date.now()-recordStart)/1000),blob};let stored=false;try{await dbTask('readwrite',s=>s.put(entry));stored=true;toast('Дубль сохранён на этом устройстве.');}catch{const url=URL.createObjectURL(blob);objectURLs.push(url);const link=document.createElement('a');link.href=url;link.download='voice-recording.'+(blob.type.includes('mp4')?'m4a':'webm');link.textContent='Скачать запись, которую не удалось сохранить';link.className='btn';$('#record-list')?.prepend(link);toast('Хранилище заполнено. Скачай запись по кнопке.');}recorder=null;recorderBusy=false;if($('#record-start'))$('#record-start').disabled=false;if($('#record-stop'))$('#record-stop').disabled=true;if($('#record-status'))$('#record-status').textContent='Запись остановлена';if(stored)listRecordings();};recorder.start(1000);$('#record-stop').disabled=false;$('#record-status').textContent='Идёт запись · 0:00';recordTicker=setInterval(()=>{if($('#record-status'))$('#record-status').textContent='Идёт запись · '+formatTime(Math.floor((Date.now()-recordStart)/1000));if(Date.now()-recordStart>=300000)stopRecording();},500);}catch(e){recorderBusy=false;recordStream?.getTracks().forEach(t=>t.stop());recordStream=null;if($('#record-start'))$('#record-start').disabled=false;toast(e.message||'Разреши доступ к микрофону в настройках браузера.');}}
function stopRecording(){if(recorder?.state==='recording')recorder.stop();}
async function listRecordings(){const el=$('#record-list');if(!el)return;try{const records=await dbTask('readonly',s=>s.getAll());if(!document.contains(el))return;const filtered=records.filter(r=>!session||r.lessonId===session.id).sort((a,b)=>b.at.localeCompare(a.at));el.innerHTML=filtered.length?'':'<p class="tiny muted">Пока нет записей</p>';filtered.forEach(r=>{const div=document.createElement('div');div.className='recording';const url=URL.createObjectURL(r.blob);objectURLs.push(url);div.innerHTML=`<strong>${esc(r.title)}</strong><div class="tiny muted">${new Date(r.at).toLocaleString('ru-RU')} · ${formatTime(r.seconds)}</div><audio controls preload="none" src="${url}"></audio><div class="row"><a class="btn secondary small" href="${url}" download="voice-${r.at.slice(0,10)}-${r.id}.${r.blob.type.includes('mp4')?'m4a':'webm'}">Скачать</a><button class="icon-btn">Удалить</button></div>`;div.querySelector('button').onclick=async()=>{if(!confirm('Удалить этот дубль с устройства?'))return;await dbTask('readwrite',s=>s.delete(r.id));div.remove();URL.revokeObjectURL(url);};el.append(div);});}catch{el.textContent='Хранение записей недоступно в этом браузере.';}}
function audioContext(){if(!ctx)ctx=new(window.AudioContext||window.webkitAudioContext)();if(ctx.state==='suspended')ctx.resume();return ctx;}
let soundGeneration=0,keyBase=48,chordRoot='C',chordType='major',chordVersion=0;
async function tone(midi,duration=.6,delay=0,volume=.14){const c=audioContext(),generation=soundGeneration;await PianoSound.prepare(c,[midi]);if(generation!==soundGeneration)return null;const voice=PianoSound.strike(c,midi,duration,delay,volume);oscillators.add(voice.source);voice.source.onended=()=>oscillators.delete(voice.source);return voice;}
function clickTone(midi){const c=audioContext(),o=c.createOscillator(),g=c.createGain(),at=c.currentTime;o.frequency.value=440*2**((midi-69)/12);o.connect(g).connect(c.destination);g.gain.setValueAtTime(.08,at);g.gain.exponentialRampToValueAtTime(.001,at+.035);o.start(at);o.stop(at+.04);oscillators.add(o);o.onended=()=>oscillators.delete(o);}
async function playExample(notes,course){const generation=soundGeneration;try{const c=audioContext();await c.resume();const midi=course==='vocal'?notes.map(n=>48+n+shift):notes.map(n=>n+shift);await PianoSound.prepare(c,midi);if(generation!==soundGeneration)return;await Promise.all(midi.map((n,i)=>tone(n,.48,i*.65)));return new Promise(resolve=>setTimeout(resolve,(midi.length-1)*650+1150));}catch{toast('Не удалось загрузить пианино. Проверь соединение.');throw Error('Piano playback unavailable');}}
function stopAudio(stopTimer=true){soundGeneration++;if(stopTimer){clearInterval(seqTimer);seqTimer=null;document.querySelectorAll('.beat.now').forEach(b=>b.classList.remove('now'));if($('#seq-play'))$('#seq-play').textContent='▶ Воспроизвести';if(metronome){clearInterval(metronome);metronome=null;if($('#metro'))$('#metro').textContent='Метроном';}}for(const o of oscillators){try{o.stop();}catch{}}oscillators.clear();}
const notesNames=['До','До♯','Ре','Ре♯','Ми','Фа','Фа♯','Соль','Соль♯','Ля','Ля♯','Си'];
function keyboard(){let html='';const whites=[0,2,4,5,7,9,11,12],blacks=[[1,1],[3,2],[6,4],[8,5],[10,6]];whites.forEach((n,i)=>html+=`<button class="key" data-note="${keyBase+n}" style="left:${i*12.5}%;width:12.5%" aria-label="${notesNames[n%12]} ${Math.floor((keyBase+n)/12)-1}">${notesNames[n%12]}</button>`);blacks.forEach(([n,pos])=>html+=`<button class="key black" data-note="${keyBase+n}" style="left:${pos*12.5-4}%;width:8%" aria-label="${notesNames[n]} ${keyBase/12-1}">${notesNames[n]}</button>`);return html;}
let metronome=null;
function chordButtons(){return Harmony.types.map(t=>`<button class="btn secondary small chord ${chordType===t.id?'selected':''}" data-chord-type="${t.id}" title="${t.name}" aria-label="${chordRoot+t.suffix}: ${t.name}" aria-pressed="${chordType===t.id}">${chordRoot+t.suffix}</button>`).join('');}
function renderTools(){return `<h1>Практика</h1><section class="card toolcard"><div class="row between"><h2>Пианино</h2><div class="row"><button class="icon-btn" id="octave-down" aria-label="Октава ниже">−</button><span id="octave-label" class="tiny">Октава ${keyBase/12-1}</span><button class="icon-btn" id="octave-up" aria-label="Октава выше">+</button></div></div><div id="piano-keys" class="keywrap">${keyboard()}</div><div class="piano-label" id="played-note" role="status">Загрузка звука…</div><div class="chord-controls"><label>Тональность<select id="chord-root">${Harmony.roots.map(r=>`<option value="${r.symbol}" ${chordRoot===r.symbol?'selected':''}>${r.symbol} · ${r.name}</option>`).join('')}</select></label><label>Обращение<select id="chord-inversion"><option value="0">Основное</option><option value="1">Первое</option><option value="2">Второе</option></select></label><label>Игра<select id="chord-mode"><option value="together">Вместе</option><option value="arp">Перебор</option></select></label></div><div class="chord-grid" id="chord-buttons">${chordButtons()}</div><div id="chord-notes" class="chord-notes" aria-live="polite"></div><div class="row"><label for="bpm">BPM</label><input id="bpm" type="number" min="40" max="180" value="80" style="width:85px"><button class="btn secondary small" id="metro">Метроном</button></div></section><div class="wide-grid"><div><section class="card toolcard"><h2>Слух</h2><div class="tools-row"><button class="btn small" id="ear-example">♪ Повторить мелодию</button><button class="btn secondary small" id="ear-low" aria-label="Ниже">−</button><button class="btn secondary small" id="ear-high" aria-label="Выше">+</button></div><p class="tiny muted" id="ear-shift">${shift>0?'+':''}${shift} полутонов</p></section><section class="card toolcard"><h2>Запись</h2><details><summary>Контрольный текст</summary><p>${CONTROL_TEXT}</p></details>${recordControls()}<div id="record-list"></div></section></div><section class="card toolcard"><h2>Ритм</h2><div id="sequencer"></div><div class="tools-row"><button class="btn small" id="seq-play">▶ Играть</button><button class="btn secondary small" id="seq-example">Пример</button></div><div class="tools-row"><button class="icon-btn" id="seq-save">Сохранить</button><label class="icon-btn" style="margin:0;cursor:pointer">Открыть<input type="file" id="seq-import" accept="application/json,.json" class="import"></label></div></section></div>`;}
function bindKeyboard(){document.querySelectorAll('[data-note]').forEach(b=>{let held=null;const release=()=>{b.classList.remove('playing');if(held){held.then(v=>v?.release()).catch(()=>{});held=null;}};const press=()=>{if(held)return;b.classList.add('playing');$('#played-note').textContent=notesNames[b.dataset.note%12]+(Math.floor(b.dataset.note/12)-1);held=tone(Number(b.dataset.note),7).catch(()=>{toast('Не удалось загрузить звук.');return null;});};b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture?.(e.pointerId);press();};b.onpointerup=release;b.onpointercancel=release;b.onlostpointercapture=release;b.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&!e.repeat){e.preventDefault();press();}};b.onkeyup=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();release();}};b.onblur=release;});}
async function playChord(){const version=++chordVersion;const inversion=Number($('#chord-inversion').value),chord=Harmony.chord(chordRoot,chordType,inversion,keyBase/12-1),arp=$('#chord-mode').value==='arp',generation=soundGeneration;$('#chord-notes').innerHTML=`<strong>${esc(chord.symbol)}</strong><span>${chord.names.map(esc).join(' · ')}</span><small>${esc(chord.type)}</small>`;document.querySelectorAll('[data-note]').forEach(k=>k.classList.toggle('chord-tone',chord.notes.includes(Number(k.dataset.note))));try{await PianoSound.prepare(audioContext(),chord.notes);if(generation!==soundGeneration||version!==chordVersion)return;await Promise.all(chord.notes.map((n,i)=>tone(n,1.3,arp?i*.16:0,.11)));}catch{toast('Не удалось загрузить пианино.');}}
function bindChordButtons(){document.querySelectorAll('[data-chord-type]').forEach(b=>b.onclick=()=>{chordType=b.dataset.chordType;$('#chord-buttons').innerHTML=chordButtons();bindChordButtons();playChord();});}
function bindTools(){bindKeyboard();bindChordButtons();const changeOctave=d=>{stopAudio(false);keyBase=Math.max(36,Math.min(60,keyBase+d*12));$('#piano-keys').innerHTML=keyboard();$('#octave-label').textContent='Октава '+(keyBase/12-1);bindKeyboard();$('#chord-notes').textContent='';};$('#octave-down').onclick=()=>changeOctave(-1);$('#octave-up').onclick=()=>changeOctave(1);$('#chord-root').onchange=()=>{chordRoot=$('#chord-root').value;$('#chord-buttons').innerHTML=chordButtons();bindChordButtons();playChord();};$('#chord-inversion').onchange=playChord;$('#chord-mode').onchange=playChord;const label=$('#played-note');PianoSound.prepare(audioContext()).then(()=>{if(document.contains(label)&&label.textContent==='Загрузка звука…')label.textContent='Нажми клавишу';}).catch(()=>{if(document.contains(label))label.textContent='Коснись клавиши, чтобы повторить загрузку';});$('#ear-example').onclick=()=>playExample([0,2,4,2,0],'vocal').catch(()=>{});const updateShift=d=>{shift=Math.max(-12,Math.min(12,shift+d));$('#ear-shift').textContent=(shift>0?'+':'')+shift+' полутонов';};$('#ear-low').onclick=()=>updateShift(-1);$('#ear-high').onclick=()=>updateShift(1);$('#metro').onclick=()=>{if(metronome){clearInterval(metronome);metronome=null;$('#metro').textContent='Метроном';return;}stopAudio();let beat=0;const tick=()=>clickTone(beat++%4===0?84:79);tick();metronome=setInterval(tick,60000/getBpm());$('#metro').textContent='Стоп';};$('#bpm').onchange=()=>{getBpm();stopAudio();};renderSequencer();$('#seq-play').onclick=toggleSequence;$('#seq-example').onclick=()=>{pattern=[[true,false,false,false,true,false,false,false],[false,false,true,false,false,false,true,false],[true,false,true,false,true,false,true,false]];persistPattern();renderSequencer();};$('#seq-save').onclick=()=>download('svoy-golos-beat.json',{format:'svoy-golos-beat',version:1,bpm:getBpm(),pattern});$('#seq-import').onchange=importBeat;bindRecorder();}
function getBpm(){const el=$('#bpm');const bpm=Math.max(40,Math.min(180,Number(el?.value)||80));if(el)el.value=bpm;return bpm;}
function persistPattern(){state.pattern=pattern;save();}
function renderSequencer(){const el=$('#sequencer');if(!el)return;el.innerHTML=`<div class="seq"><small></small>${Array.from({length:8},(_,i)=>`<small style="text-align:center">${i+1}</small>`).join('')}${['Бочка','Хлопок','Хэт'].map((name,r)=>`<small>${name}</small>${pattern[r].map((on,c)=>`<button class="beat ${on?'on':''}" data-row="${r}" data-col="${c}" aria-label="${name}, шаг ${c+1}" aria-pressed="${on}"></button>`).join('')}`).join('')}</div>`;document.querySelectorAll('.beat').forEach(b=>b.onclick=()=>{const r=Number(b.dataset.row),c=Number(b.dataset.col);pattern[r][c]=!pattern[r][c];b.classList.toggle('on',pattern[r][c]);b.setAttribute('aria-pressed',String(pattern[r][c]));persistPattern();});}
function drum(row){const c=audioContext(),at=c.currentTime;if(row===0){const o=c.createOscillator(),g=c.createGain();o.frequency.setValueAtTime(140,at);o.frequency.exponentialRampToValueAtTime(40,at+.15);g.gain.setValueAtTime(.4,at);g.gain.exponentialRampToValueAtTime(.001,at+.2);o.connect(g).connect(c.destination);o.start();o.stop(at+.22);oscillators.add(o);o.onended=()=>oscillators.delete(o);}else{const length=Math.floor(c.sampleRate*(row===1?.12:.04)),buffer=c.createBuffer(1,length,c.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<length;i++)data[i]=(Math.random()*2-1)*(1-i/length);const src=c.createBufferSource(),filter=c.createBiquadFilter(),g=c.createGain();src.buffer=buffer;filter.type='highpass';filter.frequency.value=row===1?1200:7000;g.gain.value=row===1?.18:.12;src.connect(filter).connect(g).connect(c.destination);src.start();oscillators.add(src);src.onended=()=>oscillators.delete(src);}}
function toggleSequence(){if(seqTimer){stopAudio();return;}stopAudio();audioContext();seqStep=0;const tick=()=>{document.querySelectorAll('.beat').forEach(b=>b.classList.toggle('now',Number(b.dataset.col)===seqStep));pattern.forEach((r,i)=>{if(r[seqStep])drum(i);});seqStep=(seqStep+1)%8;};tick();seqTimer=setInterval(tick,60000/getBpm()/2);$('#seq-play').textContent='■ Остановить';}
async function importBeat(e){try{const file=e.target.files[0];if(!file)return;if(file.size>100000)throw Error();const d=JSON.parse(await file.text());if(d.format!=='svoy-golos-beat'||!Array.isArray(d.pattern)||d.pattern.length!==3||!d.pattern.every(r=>Array.isArray(r)&&r.length===8&&r.every(v=>typeof v==='boolean'))||!Number.isFinite(d.bpm)||d.bpm<40||d.bpm>180)throw Error();stopAudio();pattern=d.pattern;$('#bpm').value=d.bpm;persistPattern();renderSequencer();toast('Проект открыт');}catch{toast('Не удалось открыть. Нужен проект бита, сохранённый в этом приложении.');}}
function renderProgress(){const count=Object.keys(state.mastered).filter(id=>LESSONS.some(l=>l.id===id)).length;return `<h1>Прогресс</h1><div class="stats"><div class="stat"><b>${state.sessions.length}</b><span>занятий в истории</span></div><div class="stat"><b>${count}</b><span>уроков освоено</span></div><div class="stat"><b>${new Set(state.sessions.map(s=>s.at?.slice(0,10))).size}</b><span>дней практики</span></div></div><div class="grid">${COURSES.map(courseCard).join('')}</div><section class="section"><div class="section-heading"><h2>История практики</h2></div>${state.sessions.length?state.sessions.slice().reverse().slice(0,30).map(s=>`<article class="card" style="margin-bottom:10px"><div class="eyebrow">${new Date(s.at).toLocaleDateString('ru-RU')} · ${s.rating?'лёгкость '+s.rating+'/5':'без оценки'}${s.practiced===false?' · только чтение':s.mastered?' · критерии выполнены':' · практика / повтор'}</div><h3 style="margin-top:8px">${esc(LESSONS.find(l=>l.id===s.id)?.title||'Занятие')}</h3>${s.note?`<p class="muted" style="margin:0">${esc(s.note)}</p>`:''}</article>`).join(''):'<div class="card"><h3>Первый шаг ещё впереди</h3><p class="muted">После завершения занятия здесь появятся твоя оценка лёгкости и заметка.</p><a class="btn small" href="#lesson/speech-13">Начать с речи →</a></div>'}</section><section class="card section"><h2>Сохранить свой прогресс</h2><div class="tools-row"><button class="btn small" id="export">Скачать копию</button><label class="btn secondary small" style="margin:0;cursor:pointer">Восстановить<input class="import" type="file" id="import-progress" accept=".json,application/json"></label></div></section>`;}
function download(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function importProgress(e){try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error();const d=JSON.parse(await file.text());if(d.format!=='svoy-golos-backup'||d.version!==1||!d.state||typeof d.state.completed!=='object'||Array.isArray(d.state.completed)||!Array.isArray(d.state.sessions))throw Error();const known=new Set(LESSONS.map(l=>l.id));if(!d.state.sessions.every(s=>s&&known.has(s.id)&&typeof s.at==='string'&&!isNaN(Date.parse(s.at))&&(s.rating===null||[1,2,3,4,5].includes(s.rating))&&typeof s.note==='string'&&s.note.length<=1000&&typeof s.practiced==='boolean'))throw Error();if(!confirm('Объединить резервную копию с текущим прогрессом и восстановить её маршрут, если он есть? Записи голоса не изменятся.'))return;state.completed={...state.completed,...Object.fromEntries(Object.entries(d.state.completed).filter(([id,v])=>known.has(id)&&typeof v==='string'&&!isNaN(Date.parse(v))))};if(d.state.mastered&&typeof d.state.mastered==='object'&&!Array.isArray(d.state.mastered))state.mastered={...state.mastered,...Object.fromEntries(Object.entries(d.state.mastered).filter(([id,v])=>known.has(id)&&typeof v==='string'&&!isNaN(Date.parse(v))))};if(d.state.plan)state.plan=TrainingPlan.normalize(d.state.plan,LESSONS,TrainingPlan.date());const entries=new Map([...state.sessions,...d.state.sessions].map(s=>[s.id+'|'+s.at,s]));state.sessions=[...entries.values()].sort((a,b)=>a.at.localeCompare(b.at));save();route();toast('Прогресс восстановлен');}catch{toast('Не удалось восстановить. Выбери резервную копию этого приложения.');}}
function cleanup(){pauseSession();stopAudio();stopRecording();document.querySelectorAll('audio').forEach(a=>a.pause());objectURLs.forEach(u=>URL.revokeObjectURL(u));objectURLs=[];session=null;auto=false;}
function route(){cleanup();const [page='today',id]=location.hash.replace(/^#\/?/,'').split('/');const app=$('#app');const navPage=['course','lesson'].includes(page)?'courses':page;document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===navPage);if(a.dataset.nav===navPage)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});switch(page){case 'today':case '':app.innerHTML=renderToday();bindToday();updateOffline();break;case 'courses':app.innerHTML='<h1>Занятия</h1><div class="grid section">'+COURSES.map(courseCard).join('')+'</div>';break;case 'course':app.innerHTML=renderCourse(id);break;case 'lesson':app.innerHTML=renderSession(id);renderStep();bindRecorder();break;case 'tools':app.innerHTML=renderTools();bindTools();break;case 'install':app.innerHTML=renderInstall();bindInstall();break;case 'method':app.innerHTML=renderMethod();break;case 'progress':app.innerHTML=renderProgress();$('#export').onclick=()=>download('svoy-golos-progress.json',{format:'svoy-golos-backup',version:1,state:{completed:state.completed,mastered:state.mastered,sessions:state.sessions,plan:state.plan}});$('#import-progress').onchange=importProgress;break;default:app.innerHTML=notFound();}window.scrollTo({top:0,behavior:'instant'});}
async function updateOffline(){const el=$('#offline-status');if(!el)return;try{const cache=await caches.open('svoy-golos-v6');const ready=await cache.match(new URL('app.js',location.href).href);if(document.contains(el))el.textContent=ready?'Тексты доступны без сети. Голос сохраняется кнопкой внутри занятия.':'Офлайн-копия ещё загружается. Пока нужна сеть.';}catch{el.textContent='Этот браузер не предоставил офлайн-хранилище. Нужна сеть.';}}

let installEvent=null;
const isStandalone=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
function renderInstall(){return `<a class="back" href="#today">← Сегодня</a><h1>Установить</h1><section class="card section"><p id="install-status" class="muted"></p><button id="install-app" class="btn">Установить</button><h3>Android</h3><p>Открой сайт в Chrome: меню ⋮ → «Установить приложение».</p><h3>iPhone</h3><p>Safari → «Поделиться» → «На экран Домой».</p></section>`;}
function bindInstall(){const b=$('#install-app'),p=$('#install-status');if(!b||!p)return;if(isStandalone()){b.hidden=true;p.textContent='Приложение уже открыто в отдельном окне.';return;}b.hidden=!installEvent;p.textContent=installEvent?'Браузер готов установить приложение.':'Если кнопка установки не появилась, используй меню браузера — инструкция ниже.';b.onclick=async()=>{const event=installEvent;if(!event)return;try{await event.prompt();const choice=await event.userChoice;installEvent=null;p.textContent=choice.outcome==='accepted'?'Установка запрошена. Подтверди её в браузере.':'Установку можно повторить через меню браузера.';b.hidden=true;}catch{toast('Открой меню браузера и выбери установку приложения.');}};}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;bindInstall();});
window.addEventListener('appinstalled',()=>{installEvent=null;bindInstall();toast('Приложение установлено');});
function renderMethod(){return `<a class="back" href="#today">← Сегодня</a><h1>Справка</h1><details><summary>Обучение</summary><p>Открой занятие дня, выполни практику и отметь проверенные критерии. Если навык нестабилен, он вернётся на повтор. Следующий блок начинается после освоения текущего во всех направлениях. Любой урок доступен в «Занятиях».</p><p>Перенос сохраняет задание без накопления долгов. Воскресенье — отдых. Даты берутся с устройства.</p></details><details><summary>Звук и аккорды</summary><p>Выбери тональность и тип аккорда. Обращение меняет нижний звук; перебор проигрывает ноты по очереди. Клавиши удерживаются касанием. Звуковые примеры упражнений показывают высоты равными длительностями; ритм выполняй по заданию.</p><p>Записи рояля: Alexander Holm, Salamander Grand Piano. <a href="https://github.com/Tonejs/audio/tree/master/salamander" target="_blank" rel="noopener noreferrer">Источник</a> · <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener noreferrer">CC BY 3.0</a>. Использованы девять укороченных моно-записей; остальные высоты получены транспонированием.</p></details><details><summary>Голос и самопроверка</summary><p>Пой на удобной высоте, с отдыхом. При боли или осиплости остановись. Приложение не анализирует запись и не выставляет оценку: критерии отмечаешь самостоятельно.</p><p>За рулём не читай и не управляй телефоном. При сворачивании озвучка приостанавливается.</p></details><details><summary>Сохранение</summary><p>Прогресс и записи хранятся в браузере. В «Прогрессе» можно скачать резервную копию; аудиодубли скачиваются отдельно. Для офлайн-озвучки урока нажми «Голос офлайн».</p></details><details><summary>Учебные ориентиры</summary><p><a href="https://www.abrsm.org/en-gb/piano" target="_blank" rel="noopener noreferrer">ABRSM</a> · <a href="https://www.trinitycollege.com/qualifications/music/grade-exams/about" target="_blank" rel="noopener noreferrer">Trinity</a> · <a href="https://www.nidcd.nih.gov/health/taking-care-your-voice" target="_blank" rel="noopener noreferrer">NIDCD</a>. Авторская программа; эти организации не проверяли приложение.</p></details>`;}

